def create_default_location(apps, schema_editor):
    """Создаёт локацию по умолчанию, чтобы существующие корпуса не остались
    без location при добавлении обязательного поля."""
    Location = apps.get_model('schedule_generator', 'Location')
    Location.objects.get_or_create(name='Здесь', defaults={'address': ''})


def copy_campus_to_location(apps, schema_editor):
    """Переносит данные из кампусов в локации (переименованная сущность).

    Явный INSERT ... OVERRIDING SYSTEM VALUE нужен потому, что на PostgreSQL
    таблица Location создаётся как 'generated by default as identity' и
    обычное сохранение модели с id не перебивает последовательность —
    следующая вставка без id врезалась бы в уже занятый ключ.
    """
    vendor = schema_editor.connection.vendor
    Campus = apps.get_model('schedule_generator', 'Campus')
    for campus in Campus.objects.all():
        if vendor == 'postgresql':
            schema_editor.execute(
                "INSERT INTO schedule_generator_location (id, name, address) "
                "OVERRIDING SYSTEM VALUE VALUES (%s, %s, %s)",
                [campus.pk, campus.name, campus.address],
            )
        else:
            Location = apps.get_model('schedule_generator', 'Location')
            Location.objects.create(id=campus.pk, name=campus.name, address=campus.address)
    if vendor == 'postgresql' and Campus.objects.exists():
        max_pk = Campus.objects.aggregate(m=models.Max('pk'))['m'] or 0
        schema_editor.execute(
            "SELECT setval(pg_get_serial_sequence('schedule_generator_location', 'id'), %s)",
            [max_pk],
        )


def assign_buildings_to_locations(apps, schema_editor):
    """Привязывает корпуса к локациям: к унаследованной локации с тем же id,
    что был у их кампуса, иначе — к первой доступной."""
    Building = apps.get_model('schedule_generator', 'Building')
    Location = apps.get_model('schedule_generator', 'Location')
    first_location = Location.objects.order_by('id').first()
    if first_location is None:
        return
    valid_ids = set(Location.objects.values_list('id', flat=True))
    for building in Building.objects.all():
        location_id = getattr(building, 'campus_id', None)
        building.location_id = location_id if location_id in valid_ids else first_location.pk
        building.save(force_update=True)


